const getColors = (num, system?: "cohesion" | "magnetic") => {
	if (typeof num !== "number") return [];

	if (system === "magnetic") {
		const colors = [
			"var(--hbr-color-accent-a-base, #7D8AFF)",
			"var(--hbr-color-accent-b-base, #B02863)",
			"var(--hbr-color-accent-c-base, #F2638C)",
			"var(--hbr-color-accent-d-base, #753BCC)",
			"var(--hbr-color-accent-e-base, #6BA32A)",
			"var(--hbr-color-accent-f-base, #AD3907)",
			"var(--hbr-color-accent-g-base, #04A4B0)",
			"var(--hbr-color-accent-h-base, #006773)",
			"var(--hbr-color-accent-i-base, #E85FC6)",
			"var(--hbr-color-accent-j-base, #545C8A)",
		];
		return colors.slice(0, num);
	}
	const colors = [
		"var(--hbr-color-chart-1b, #3a49b5)",
		"var(--hbr-color-chart-2d, #b779fc)",
		"var(--hbr-color-chart-3b, #0099b4)",
		"var(--hbr-color-chart-4d, #c5bee0)",
		"var(--hbr-color-chart-5a, #9c2f91)",
		"var(--hbr-color-chart-6d, #74c7c0)",
		"var(--hbr-color-chart-7b, #d5488f)",
		"var(--hbr-color-chart-8c, #9593de)",
		"var(--hbr-color-chart-9a, #a21eff)",
		"var(--hbr-color-chart-10e, #90caf9)",
	];
	return colors.slice(0, num);
};

export default getColors;
